176: ## 3. Deterministic Mock Network Layer (Offline Router & Fixtures)
177: 
178: ### 3.1 Mock Fetch Interceptor Architecture
179: The harness replaces `window.fetch` with a deterministic router. The router pattern-matches incoming URL strings, inspects query parameters, and responds synchronously or asynchronously with pre-constructed JSON fixtures:
180: 
181: ```javascript
182: function installMockFetch(window, customRoutes = {}) {
183:   const routes = Object.assign({}, DEFAULT_MOCK_ROUTES, customRoutes);
184:   window._fetchCalls = [];
185: 
186:   window.fetch = function (url, options = {}) {
187:     window._fetchCalls.push({ url: String(url), options });
188:     const urlStr = String(url);
189: 
190:     for (const pattern in routes) {
191:       if (routes.hasOwnProperty(pattern)) {
192:         const isMatch = pattern.startsWith('^') 
193:           ? new RegExp(pattern).test(urlStr) 
194:           : urlStr.indexOf(pattern) !== -1;
195: 
196:         if (isMatch) {
197:           const handler = routes[pattern];
198:           const responseData = typeof handler === 'function' ? handler(urlStr, options) : handler;
199: 
200:           if (responseData && responseData._errorStatus) {
201:             return Promise.resolve({
202:               ok: false,
203:               status: responseData._errorStatus,
204:               statusText: responseData._errorText || 'Error',
205:               json: () => Promise.reject(new Error(responseData._errorText || 'HTTP Error')),
206:               text: () => Promise.resolve(responseData._errorText || 'HTTP Error')
207:             });
208:           }
209: 
210:           return Promise.resolve({
211:             ok: true,
212:             status: 200,
213:             statusText: 'OK',
214:             json: () => Promise.resolve(JSON.parse(JSON.stringify(responseData))),
215:             text: () => Promise.resolve(JSON.stringify(responseData))
216:           });
217:         }
218:       }
219:     }
220: 
221:     console.warn('[MockFetch] Unhandled URL intercepted:', urlStr);
222:     return Promise.resolve({
223:       ok: false,
224:       status: 404,
225:       statusText: 'Not Found',
226:       json: () => Promise.resolve({ error: 'Endpoint not mocked', url: urlStr }),
227:       text: () => Promise.resolve('{"error":"Endpoint not mocked"}')
228:     });
229:   };
230: }
231: ```
