  // ---------------------------------------------------------------------------
  // 4. Memory-Bounded LRU / TTL Cache (Max 100 entries for webOS TV 1.5GB RAM)
  // ---------------------------------------------------------------------------
  function LruTtlCache(capacity) {
    this.capacity = capacity || 100;
    this.store = new Map();
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
  }

  LruTtlCache.prototype.get = function (key) {
    if (!this.store.has(key)) {
      this.misses++;
      return null;
    }
    var entry = this.store.get(key);
    var now = Date.now();
    if (now > entry.expiresAt) {
      this.store.delete(key);
      this.misses++;
      return null;
    }
    // Refresh LRU order (delete & set moves key to MRU tail)
    this.store.delete(key);
    this.store.set(key, entry);
    this.hits++;
    return entry.data;
  };

  LruTtlCache.prototype.set = function (key, data, ttlSeconds) {
    var ttl = (ttlSeconds !== undefined ? ttlSeconds : 900) * 1000;
    var expiresAt = Date.now() + ttl;

    if (this.store.has(key)) {
      this.store.delete(key);
    } else if (this.store.size >= this.capacity) {
      var oldestKey = this.store.keys().next().value;
      this.store.delete(oldestKey);
      this.evictions++;
    }

    this.store.set(key, {
      data: data,
      expiresAt: expiresAt,
      storedAt: Date.now()
    });
  };

  LruTtlCache.prototype.peek = function (key) {
    var entry = this.store.get(key);
    return entry ? entry.data : null;
  };

  LruTtlCache.prototype.clear = function () {
    this.store.clear();
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
  };

  LruTtlCache.prototype.getStats = function () {
    return {
      size: this.store.size,
      capacity: this.capacity,
      hits: this.hits,
      misses: this.misses,
      evictions: this.evictions
    };
  };

  // ---------------------------------------------------------------------------
  // 5. Internal State
  // ---------------------------------------------------------------------------
  var state = {
    config: Object.assign({}, DEFAULT_CONFIG),
    cache: new LruTtlCache(DEFAULT_CONFIG.cacheCapacity),
    mockMode: false,
    mockLatencyMs: 0,
    mockFixtures: new Map()
  };

  // ---------------------------------------------------------------------------
  // 6. HTTP Engine with AbortController Timeout & Stale Fallback
  // ---------------------------------------------------------------------------
  function fetchWithTimeout(url, options, timeoutMs) {
    var timeout = timeoutMs || state.config.requestTimeoutMs;
    var controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    var signal = controller ? controller.signal : undefined;
    var fetchOpts = Object.assign({}, options || {}, { signal: signal });

    var timerId = null;
    var timeoutPromise = new Promise(function (_, reject) {
      timerId = setTimeout(function () {
        if (controller) {
          try { controller.abort(); } catch (_) {}
        }
        var err = new Error('Request timed out after ' + timeout + 'ms');
        err.code = 'TIMEOUT';
        err.url = url;
        reject(err);
      }, timeout);
    });

    var fetchPromise;
    try {
      var fetchFn = typeof window !== 'undefined' && window.fetch ? window.fetch : (typeof fetch !== 'undefined' ? fetch : null);
      if (!fetchFn) {
        throw new Error('No fetch implementation available');
      }
      fetchPromise = fetchFn(url, fetchOpts);
    } catch (e) {
      if (timerId) clearTimeout(timerId);
      return Promise.reject(e);
    }

    return Promise.race([fetchPromise, timeoutPromise]).then(function (response) {
      if (timerId) clearTimeout(timerId);
      return response;
    }).catch(function (err) {
      if (timerId) clearTimeout(timerId);
      throw err;
    });
  }

  function executeRequest(url, cacheKey, ttlSeconds) {
    // Check LRU cache first
    var cached = state.cache.get(cacheKey);
    if (cached !== null) {
      return Promise.resolve(cached);
    }

    // Check Mock Mode fixtures
    if (state.mockMode) {
      var mockMatch = null;
      var entries = state.mockFixtures.entries();
      var nextEntry = entries.next();
      while (!nextEntry.done) {
        var pattern = nextEntry.value[0];
        var fixture = nextEntry.value[1];
        if (typeof pattern === 'string' && url.indexOf(pattern) !== -1) {
          mockMatch = fixture;
          break;
        } else if (pattern instanceof RegExp && pattern.test(url)) {
          mockMatch = fixture;
          break;
        }
        nextEntry = entries.next();
      }

      if (mockMatch !== null) {
        state.cache.set(cacheKey, mockMatch, ttlSeconds);
        return new Promise(function (resolve) {
          setTimeout(function () {
            resolve(JSON.parse(JSON.stringify(mockMatch)));
          }, state.mockLatencyMs);
        });
      }
    }

    return fetchWithTimeout(url, { method: 'GET' }).then(function (res) {
      if (!res.ok) {
        var httpErr = new Error('HTTP ' + res.status + ' ' + (res.statusText || ''));
        httpErr.code = 'HTTP_ERROR';
        httpErr.status = res.status;
        httpErr.url = url;
        throw httpErr;
      }
      return res.json();
    }).then(function (json) {
      state.cache.set(cacheKey, json, ttlSeconds);
      return json;
    }).catch(function (err) {
      // Stale-While-Revalidate fallback
      var stale = state.cache.peek(cacheKey);
      if (stale !== null) {
        console.warn('[TmdbClient] Network error (' + err.message + '). Serving stale cache for: ' + cacheKey);
        return stale;
      }
      console.error('[TmdbClient] Request failed (' + url + '):', err.message);
      // Return safe structured failure instead of unhandled crash
      return { error: true, code: err.code || 'NETWORK_ERROR', message: err.message, results: [] };
    });
  }

  // ---------------------------------------------------------------------------
  // 7. Normalization Layer
  // ---------------------------------------------------------------------------
  function formatRuntime(minutes) {
    if (!minutes || typeof minutes !== 'number' || minutes <= 0) return '—';
    var hrs = Math.floor(minutes / 60);
    var mins = minutes % 60;
    if (hrs > 0 && mins > 0) return hrs + 'h ' + mins + 'm';
    if (hrs > 0) return hrs + 'h';
    return mins + 'm';
  }

  function normalizeItem(raw, defaultType) {
    if (!raw) return null;
    var type = raw.media_type || defaultType || (raw.first_air_date ? 'tv' : 'movie');
    var title = raw.title || raw.name || raw.original_title || raw.original_name || 'Untitled';
    var originalTitle = raw.original_title || raw.original_name || title;
    var releaseDate = raw.release_date || raw.first_air_date || '';
    var year = releaseDate ? releaseDate.substring(0, 4) : '';
    var voteAvg = typeof raw.vote_average === 'number' ? Math.round(raw.vote_average * 10) / 10 : 0.0;

    var genreIds = raw.genre_ids || (raw.genres ? raw.genres.map(function (g) { return g.id; }) : []) || [];
    var genreNames = [];
    var genreDict = GENRE_FALLBACK[type] || {};
    for (var i = 0; i < genreIds.length; i++) {
      var gId = genreIds[i];
      if (genreDict[gId]) {
        genreNames.push(genreDict[gId]);
      }
    }

    return {
      id: raw.id,
      tmdbId: raw.id,
      type: type,
      title: title,
      originalTitle: originalTitle,
      overview: raw.overview || '',
      releaseDate: releaseDate,
      year: year,
      rating: voteAvg,
      ratingDisplay: voteAvg > 0 ? voteAvg.toFixed(1) : 'NR',
      voteCount: raw.vote_count || 0,
      posterUrl: getPosterUrl(raw.poster_path, 'w500'),
      posterThumbUrl: getPosterUrl(raw.poster_path, 'w342'),
      backdropUrl: getBackdropUrl(raw.backdrop_path, 'w1280'),
      genres: genreNames,
      genreIds: genreIds,
      popularity: raw.popularity || 0
    };
  }

  function normalizeDetails(raw, defaultType) {
    if (!raw) return null;
    var base = normalizeItem(raw, defaultType);
    if (!base) return null;

    var runtime = raw.runtime || (raw.episode_run_time && raw.episode_run_time[0]) || 0;
    var tagline = raw.tagline || '';
    var status = raw.status || 'Released';
    var logoUrl = getLogoUrl(raw.images);

    // Cast members
    var castMembers = [];
    if (raw.credits && raw.credits.cast) {
      var rawCast = raw.credits.cast.slice(0, 15);
      for (var c = 0; c < rawCast.length; c++) {
        var member = rawCast[c];
        castMembers.push({
          id: member.id,
          name: member.name,
          character: member.character || '',
          profileUrl: getProfileUrl(member.profile_path, 'w185'),
          order: member.order || c
        });
      }
    }

    // Seasons for TV
    var seasons = [];
    if (raw.seasons) {
      for (var s = 0; s < raw.seasons.length; s++) {
        var sz = raw.seasons[s];
        if (sz.season_number > 0) {
          seasons.push({
            id: sz.id,
            seasonNumber: sz.season_number,
            name: sz.name || ('Season ' + sz.season_number),
            episodeCount: sz.episode_count || 0,
            posterUrl: getPosterUrl(sz.poster_path, 'w342'),
            airDate: sz.air_date || ''
          });
        }
      }
    }

    // Recommendations & Similar
    var recommendations = [];
    if (raw.recommendations && raw.recommendations.results) {
      recommendations = raw.recommendations.results.slice(0, 12).map(function (it) {
        return normalizeItem(it, base.type);
      });
    }

    var similar = [];
    if (raw.similar && raw.similar.results) {
      similar = raw.similar.results.slice(0, 12).map(function (it) {
        return normalizeItem(it, base.type);
      });
    }

    return Object.assign({}, base, {
      tagline: tagline,
      runtime: runtime,
      formattedRuntime: formatRuntime(runtime),
      status: status,
      logoUrl: logoUrl,
      numberOfSeasons: raw.number_of_seasons || (seasons.length > 0 ? seasons.length : 1),
      numberOfEpisodes: raw.number_of_episodes || 0,
      seasons: seasons,
      cast: castMembers,
      recommendations: recommendations,
      similar: similar
    });
  }

  // ---------------------------------------------------------------------------
  // 8. Image Resolution Helpers & Fallbacks
  // ---------------------------------------------------------------------------
  function getPosterUrl(path, size) {
    if (!path) return PLACEHOLDER_POSTER;
    var sz = size || 'w500';
    return state.config.imageBaseUrl + sz + path;
  }

  function getBackdropUrl(path, size) {
    if (!path) return PLACEHOLDER_BACKDROP;
    var sz = size || 'w1280';
    return state.config.imageBaseUrl + sz + path;
  }

  function getProfileUrl(path, size) {
    if (!path) return PLACEHOLDER_PROFILE;
    var sz = size || 'w185';
    return state.config.imageBaseUrl + sz + path;
  }

  function getStillUrl(path, size) {
    if (!path) return PLACEHOLDER_STILL;
    var sz = size || 'w500';
    return state.config.imageBaseUrl + sz + path;
  }

  function getImageUrl(path, type, size) {
    if (!path) {
      if (type === 'backdrop') return PLACEHOLDER_BACKDROP;
      if (type === 'still') return PLACEHOLDER_STILL;
      if (type === 'profile') return PLACEHOLDER_PROFILE;
      return PLACEHOLDER_POSTER;
    }
    if (type === 'backdrop') return getBackdropUrl(path, size);
    if (type === 'still') return getStillUrl(path, size);
    if (type === 'profile') return getProfileUrl(path, size);
    return getPosterUrl(path, size);
  }

  function getLogoUrl(images, preferredLang) {
    if (!images || !images.logos || !images.logos.length) return null;
    var lang = preferredLang || 'en';
    var logos = images.logos;

    // Filter English logos first
    var enLogos = logos.filter(function (l) { return l.iso_639_1 === lang; });
    var chosen = enLogos.length > 0 ? enLogos[0] : logos[0];
    if (!chosen || !chosen.file_path) return null;

    return state.config.imageBaseUrl + 'w500' + chosen.file_path;
  }

  function handleImageError(imgElement, type) {
    if (!imgElement || imgElement._hasFailed) return;
    imgElement._hasFailed = true;
    imgElement.onerror = null;

    switch (type) {
      case 'backdrop':
        imgElement.src = PLACEHOLDER_BACKDROP;
        break;
      case 'still':
        imgElement.src = PLACEHOLDER_STILL;
        break;
      case 'profile':
        imgElement.src = PLACEHOLDER_PROFILE;
        break;
      case 'poster':
      default:
        imgElement.src = PLACEHOLDER_POSTER;
        break;
    }
  }

