  function getTrending(mediaType, timeWindow, page) {
    var mType = mediaType || 'all';
    var tWindow = timeWindow || 'day';
    var p = page || 1;
    var url = state.config.baseUrl + '/trending/' + mType + '/' + tWindow +
      '?api_key=' + state.config.apiKey +
      '&language=en-US' +
      '&page=' + p;
    var cacheKey = 'trending:' + mType + ':' + tWindow + ':' + p;

    return executeRequest(url, cacheKey, 1800).then(function (res) {
      if (res.error) return res;
      var results = (res.results || []).map(function (item) {
        return normalizeItem(item, mType === 'all' ? undefined : mType);
      });
      return {
        page: res.page || p,
        results: results,
        totalPages: res.total_pages || 1,
        totalResults: res.total_results || results.length
      };
