  function discover(mediaType, params) {
    var mType = mediaType || 'movie';
    var p = (params && params.page) || 1;
    var sortBy = (params && params.sortBy) || 'popularity.desc';
    var queryParams = [
      'api_key=' + state.config.apiKey,
      'language=' + ((params && params.language) || 'en-US'),
      'page=' + p,
      'sort_by=' + sortBy,
      'include_adult=false'
    ];

    if (params && (params.genreId || params.withGenres)) {
      var genres = params.genreId || params.withGenres;
      var genreStr = Array.isArray(genres) ? genres.join(',') : String(genres);
      queryParams.push('with_genres=' + encodeURIComponent(genreStr));
    }

    if (params && params.year) {
      var yearParam = mType === 'tv' ? 'first_air_date_year' : 'primary_release_year';
      queryParams.push(yearParam + '=' + encodeURIComponent(params.year));
    }

    if (params && params.withWatchProviders) {
      queryParams.push('with_watch_providers=' + encodeURIComponent(params.withWatchProviders));
      queryParams.push('watch_region=' + encodeURIComponent(params.watchRegion || 'US'));
    }

    if (sortBy && sortBy.indexOf('vote_average') !== -1) {
      queryParams.push('vote_count.gte=' + ((params && params.voteCountGte) || 50));
    }

    var url = state.config.baseUrl + '/discover/' + mType + '?' + queryParams.join('&');
    var cacheKey = 'discover:' + mType + ':' + queryParams.slice(1).sort().join('&');

    return executeRequest(url, cacheKey, 900).then(function (res) {
      if (res.error) return res;
      var results = (res.results || []).map(function (item) {
        return normalizeItem(item, mType);
      });
      return {
        page: res.page || p,
        results: results,
        totalPages: res.total_pages || 1,
        totalResults: res.total_results || results.length
      };
    });
  }

  function getGenres(mediaType) {
    var mType = mediaType || 'movie';
    var url = state.config.baseUrl + '/genre/' + mType + '/list?api_key=' + state.config.apiKey + '&language=en-US';
    var cacheKey = 'genres:' + mType;

    return executeRequest(url, cacheKey, 86400).then(function (res) {
      var rawGenres = (res && res.genres) || [];
      if (!rawGenres.length && GENRE_FALLBACK[mType]) {
        rawGenres = Object.keys(GENRE_FALLBACK[mType]).map(function (id) {
          return { id: parseInt(id, 10), name: GENRE_FALLBACK[mType][id] };
        });
      }
      var genreMap = {};
      rawGenres.forEach(function (g) { genreMap[g.id] = g.name; });
      return {
        genres: rawGenres,
        map: genreMap
      };
    }).catch(function () {
      var fallbackList = [];
      var dict = GENRE_FALLBACK[mType] || {};
      for (var k in dict) {
        if (dict.hasOwnProperty(k)) fallbackList.push({ id: parseInt(k, 10), name: dict[k] });
      }
      return { genres: fallbackList, map: dict };
    });
  }

  function getDetails(mediaType, id, options) {
    var mType = mediaType || 'movie';
    var url = state.config.baseUrl + '/' + mType + '/' + id +
      '?api_key=' + state.config.apiKey +
      '&language=en-US' +
      '&append_to_response=credits,recommendations,similar,images' +
