  function getTvSeason(tvId, seasonNumber) {
    var sNum = seasonNumber !== undefined ? seasonNumber : 1;
    var url = state.config.baseUrl + '/tv/' + tvId + '/season/' + sNum +
      '?api_key=' + state.config.apiKey +
      '&language=en-US';
    var cacheKey = 'season:' + tvId + ':' + sNum;

    return executeRequest(url, cacheKey, 3600).then(function (res) {
      if (res.error) return res;
      var rawEpisodes = res.episodes || [];
      var episodes = rawEpisodes.map(function (ep) {
        return {
          id: ep.id,
          episodeNumber: ep.episode_number,
          seasonNumber: ep.season_number || sNum,
