    var url = state.config.baseUrl + '/search/multi' +
      '?api_key=' + state.config.apiKey +
      '&language=en-US' +
      '&query=' + encodeURIComponent(cleanQuery) +
      '&page=' + p +
      '&include_adult=false';
    var cacheKey = 'search:' + cleanQuery.toLowerCase() + ':' + p;

    return executeRequest(url, cacheKey, 300).then(function (res) {
      if (res.error) return res;
      var filtered = (res.results || []).filter(function (item) {
        return item.media_type === 'movie' || item.media_type === 'tv' || (!item.media_type && (item.title || item.name));
      }).map(function (item) {
        return normalizeItem(item);
