  // ---------------------------------------------------------------------------
  // 10. Public API Interface
  // ---------------------------------------------------------------------------
  var TmdbClient = {
    init: function (config) {
      if (config) {
        state.config = Object.assign({}, DEFAULT_CONFIG, config);
        if (config.cacheCapacity && config.cacheCapacity !== state.cache.capacity) {
          state.cache = new LruTtlCache(config.cacheCapacity);
        }
      }
    },
    getConfig: function () {
      return Object.assign({}, state.config);
