console.log('[CinejoyApp] Switching view: ' + this.state.currentView + ' -> ' + viewName);
if (this.state.currentView && typeof window !== 'undefined' && window.SpatialNav) {
  window.SpatialNav.saveFocus(this.state.currentView);
}

if (this.state.currentView === 'search' && viewName !== 'search' && global.SearchViewController) {
  global.SearchViewController.deactivate();
}

if (viewName === 'details') {
  if (this.state.currentView !== 'details' && this.state.currentView !== 'player') {
    this.state.detailsOriginView = this.state.currentView;
  }
} else if (viewName !== 'player') {
  this.state.detailsOriginView = null;
}

this.state.previousView = this.state.currentView;
this.state.currentView = viewName;

// Update URL hash
if (window.location.hash !== '#' + viewName) {
  window.location.hash = '#' + viewName;
}

// Hide all views
var allViews = document.querySelectorAll('.view');
allViews.forEach(function (v) {
  v.classList.remove('active');
});

// Show target view
var targetViewEl = document.getElementById('view-' + viewName);
if (targetViewEl) {
  targetViewEl.classList.add('active');
  // Reset scroll position to top
  var scrollPane = targetViewEl.querySelector('.view-scroll-pane');
  if (scrollPane) {
    scrollPane.scrollTop = 0;
  }
}

// Invoke view controller activate hooks if present
if (viewName === 'home' && global.HomeViewController) {
  global.HomeViewController.activate();
} else if (viewName === 'movies' && global.MoviesViewController) {
  global.MoviesViewController.activate();
} else if (viewName === 'series' && global.SeriesViewController) {
  global.SeriesViewController.activate();
} else if (viewName === 'search' && global.SearchViewController) {
  global.SearchViewController.activate();
} else if (viewName === 'details' && global.DetailsViewController) {
  global.DetailsViewController.activate(data);
}

