function installMockFetch(window, customRoutes) {
  var routes = Object.assign({}, DEFAULT_MOCK_ROUTES, customRoutes || {});
  window._fetchCalls = [];

  window.fetch = function (url, options) {
    var urlStr = String(url);
    window._fetchCalls.push({ url: urlStr, options: options || {} });

    for (var pattern in routes) {
      if (routes.hasOwnProperty(pattern)) {
        var isMatch = pattern.startsWith('^')
          ? new RegExp(pattern).test(urlStr)
          : urlStr.indexOf(pattern) !== -1;

        if (isMatch) {
          var handler = routes[pattern];
          var responseData = typeof handler === 'function' ? handler(urlStr, options) : handler;

          if (responseData && responseData._errorStatus) {
            return Promise.resolve({
              ok: false,
              status: responseData._errorStatus,
              statusText: responseData._errorText || 'Error',
              json: function () { return Promise.reject(new Error(responseData._errorText || 'HTTP Error')); },
              text: function () { return Promise.resolve(responseData._errorText || 'HTTP Error'); }
            });
          }

          return Promise.resolve({
            ok: true,
            status: 200,
            statusText: 'OK',
            json: function () { return Promise.resolve(JSON.parse(JSON.stringify(responseData))); },
            text: function () { return Promise.resolve(JSON.stringify(responseData)); }
          });
        }
      }
    }

    // Default 404
    return Promise.resolve({
      ok: false,
      status: 404,
      statusText: 'Not Found',
      json: function () { return Promise.resolve({ error: true, message: 'Not found: ' + urlStr }); },
      text: function () { return Promise.resolve('{"error":"Not found"}'); }
    });
  };
}

