// -----------------------------------------------------------------------------
function createM4Harness(options) {
  var opts = options || {};
  var initialRoute = opts.initialRoute || 'home';
  var customRoutes = opts.mockRoutes || {};

  var htmlPath = path.resolve(__dirname, 'index.html');
  var configPath = path.resolve(__dirname, 'js/config.js');
  var navPath = path.resolve(__dirname, 'js/navigation.js');
  var tmdbPath = path.resolve(__dirname, 'js/tmdb.js');
  var homePath = path.resolve(__dirname, 'js/views/home.js');
  var catalogPath = path.resolve(__dirname, 'js/views/catalog.js');
  var searchPath = path.resolve(__dirname, 'js/views/search.js');
  var detailsPath = path.resolve(__dirname, 'js/views/details.js');
  var appPath = path.resolve(__dirname, 'js/app.js');

  var html = fs.readFileSync(htmlPath, 'utf8');
  var dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  var window = dom.window;

  window.__TEST_M4__ = true;
  installScrollMocks(window);
  installLayoutMock(window);
  installMockFetch(window, customRoutes);

  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(tmdbPath, 'utf8'));
  window.eval(fs.readFileSync(homePath, 'utf8'));
  window.eval(fs.readFileSync(catalogPath, 'utf8'));
  window.eval(fs.readFileSync(searchPath, 'utf8'));
  window.eval(fs.readFileSync(detailsPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (window.CinejoyApp && typeof window.CinejoyApp.init === 'function') {
    window.CinejoyApp.init();
  }

  return {
    dom: dom,
    window: window,
    app: window.CinejoyApp,
    nav: window.SpatialNav,
    tmdb: window.TmdbClient,
    home: window.HomeViewController,
    movies: window.MoviesViewController,
    series: window.SeriesViewController,
    search: window.SearchViewController,
    details: window.DetailsViewController
  };
}

function sendKey(window, key, keyCode) {
  var event = new window.KeyboardEvent('keydown', {
    key: key,
    keyCode: keyCode,
    which: keyCode,
    bubbles: true,
    cancelable: true
  });
  window.dispatchEvent(event);
  return event;
}

function stepKey(window, key, keyCode) {
  if (window.SpatialNav && typeof window.SpatialNav.resetThrottle === 'function') {
    window.SpatialNav.resetThrottle();
  }
  return sendKey(window, key, keyCode);
}

