    var placeholder = h.window.document.getElementById('search-query-placeholder');
    assert.strictEqual(placeholder.style.display, 'none', 'Placeholder must hide when query text exists');
  });

  await check('S4', '4', 'Special Keys Handling (SPACE, BACKSPACE, CLEAR)', async function () {
    var h = createM4Harness();
    h.app.switchView('search');
    await sleep(20);

    h.search.query = 'DUNE';
    h.search.updateInputDisplay();

    var keySpace = h.window.document.querySelector('.key-btn[data-key="SPACE"]');
    var keyBackspace = h.window.document.querySelector('.key-btn[data-key="BACKSPACE"]');
    var keyClear = h.window.document.querySelector('.key-btn[data-key="CLEAR"]');

    keySpace.click();
    assert.strictEqual(h.search.query, 'DUNE ', 'SPACE must append space character');

    keyBackspace.click();
    assert.strictEqual(h.search.query, 'DUNE', 'BACKSPACE must remove last character');

    keyClear.click();
    assert.strictEqual(h.search.query, '', 'CLEAR must reset query to empty');
  });

  await check('S4', '5', 'Debounced Live Multi-Search Dispatch', async function () {
    var h = createM4Harness();
    h.app.switchView('search');
    await sleep(20);

    var callsBefore = h.window._fetchCalls.length;
    h.search.query = 'Dune';
    h.search.scheduleSearch();

    // Immediately after typing, fetch should NOT have fired yet (debounced)
    var callsImmediate = h.window._fetchCalls.length;
    assert.strictEqual(callsImmediate, callsBefore, 'Should not fire search fetch immediately before 300ms debounce');

    // Wait 350ms to cross debounce threshold
    await sleep(350);
    var foundSearchCall = h.window._fetchCalls.some(function (c) {
      return c.url.indexOf('/search/multi') !== -1 && c.url.indexOf('query=Dune') !== -1;
    });
    assert.ok(foundSearchCall, 'Must fire multi-search query after debounce window elapses');
  });

  await check('S4', '6', 'Search Results Grid Population & Count Label', async function () {
    var h = createM4Harness();
    h.app.switchView('search');
    await sleep(20);

    h.search.query = 'Dune';
    await h.search.executeSearch();

    var resultCards = h.window.document.querySelectorAll('#search-results-grid .card-poster');
    assert.ok(resultCards.length >= 2, `Search results grid must populate matching cards (found ${resultCards.length})`);

    var countLabel = h.window.document.getElementById('search-results-count');
    assert.ok(countLabel && countLabel.textContent.indexOf('matches') !== -1, 'Results count label must indicate match count');
  });

  await check('S4', '7', 'Empty & Error Query State Handling', async function () {
    var h = createM4Harness();
    h.app.switchView('search');
    await sleep(20);

    // Empty search query results
    h.search.query = 'UNKNOWN_TITLES_XYZ';
    h.search.renderResults([]);

    var emptyState = h.window.document.querySelector('#search-results-grid .search-empty-state');
    assert.ok(emptyState, 'Empty state container rendered in search grid');
    assert.ok(emptyState.textContent.indexOf('No results found for "UNKNOWN_TITLES_XYZ"') !== -1 ||
              emptyState.textContent.indexOf('No titles found') !== -1,
              'Empty state must mention query name');

    // Error state
    h.search.renderError();
    var errState = h.window.document.querySelector('#search-results-grid .search-error-state');
    assert.ok(errState, 'Error state container rendered on search network failure');
  });

  // ===========================================================================
  // SUITE 5: Content Details & TV Episode Selector Suite
  // ===========================================================================
  console.log(`\n${C.cyan}▶ SUITE 5: Content Details & TV Episode Selector Suite${C.reset}`);

  await check('S5', '1', 'Content Metadata & Backdrop Binding', async function () {
    var h = createM4Harness();
    h.app.openDetails({ id: 693134, type: 'movie', title: 'Dune: Part Two' });
    await sleep(20);

    var titleEl = h.window.document.getElementById('details-title');
    assert.strictEqual(titleEl.textContent, 'Dune: Part Two');

    var yearEl = h.window.document.getElementById('details-meta-year');
    assert.strictEqual(yearEl.textContent, '2024');

    var ratingEl = h.window.document.getElementById('details-meta-rating');
    assert.ok(ratingEl && ratingEl.textContent.indexOf('8.6') !== -1, 'Rating must display 8.6');

    var backdropImg = h.window.document.querySelector('#view-details .details-backdrop-img');
    assert.ok(backdropImg && backdropImg.src.indexOf('http') === 0, 'Backdrop image must be bound');
  });

  await check('S5', '2', 'Cast Carousel Dynamic Generation', async function () {
    var h = createM4Harness();
    await h.details.loadDetails(693134, 'movie');
    await sleep(20);

    var castItems = h.window.document.querySelectorAll('#details-cast-rail .cast-item');
    assert.ok(castItems.length >= 5, `Cast rail must render >= 5 cast cards (found ${castItems.length})`);

    var firstActor = castItems[0].querySelector('.cast-name');
    assert.strictEqual(firstActor.textContent, 'Timothée Chalamet');
    assert.strictEqual(castItems[0].getAttribute('data-nav'), 'true', 'Cast card must declare data-nav="true"');
  });

  await check('S5', '3', 'TV Show Season Tab Switching & Episode Fetch', async function () {
    var h = createM4Harness();
    await h.details.loadDetails(94997, 'tv');
    await sleep(20);

    var seasonPills = h.window.document.querySelectorAll('#view-details .season-selector-bar .season-pill');
    assert.ok(seasonPills.length >= 2, `Season bar must show at least 2 seasons (found ${seasonPills.length})`);

    // Switch to Season 2
    var season2Pill = Array.from(seasonPills).find(function (p) {
      return p.getAttribute('data-season') === '2';
    });
    assert.ok(season2Pill, 'Season 2 pill exists');
    season2Pill.click();
    await sleep(20);

    var foundSeason2Call = h.window._fetchCalls.some(function (c) {
      return c.url.indexOf('/tv/94997/season/2') !== -1;
    });
    assert.ok(foundSeason2Call, 'Clicking Season 2 tab must fetch season 2 metadata from TMDB');
  });

  await check('S5', '4', 'Episode Card List & 16:9 Aspect Ratio (320x180px)', async function () {
    var h = createM4Harness();
    await h.details.loadDetails(94997, 'tv');
    await sleep(20);

    var epCards = h.window.document.querySelectorAll('#details-episodes-rail .card-episode');
    assert.ok(epCards.length >= 2, `Episode rail must render episodes (found ${epCards.length})`);

    var rect = epCards[0].getBoundingClientRect();
    assert.strictEqual(rect.width, 320, 'Episode card width must be 320px');
    assert.strictEqual(rect.height, 180, 'Episode card height must be 180px (16:9 aspect ratio)');

    var badge = epCards[0].querySelector('.episode-badge');
    assert.strictEqual(badge.textContent, 'E1', 'Episode badge must display E1');
  });

  await check('S5', '5', '"Watch Now" / Play Action Payload Construction', async function () {
    var h = createM4Harness();
    await h.details.loadDetails(94997, 'tv');
    await sleep(20);

    var epCards = h.window.document.querySelectorAll('#details-episodes-rail .card-episode');
    assert.ok(epCards.length >= 2, 'Episodes exist');

    // Click episode 2
    epCards[1].click();
    assert.strictEqual(h.app.state.currentView, 'player', 'Clicking episode must transition to player view');
  });

  await check('S5', '6', 'Similar / Recommended Titles Shelf', async function () {
    var h = createM4Harness();
    await h.details.loadDetails(693134, 'movie');
    await sleep(20);

    var recCards = h.window.document.querySelectorAll('#details-recommendations-rail .card-poster');
    assert.ok(recCards.length >= 1, `Recommendations rail must contain poster cards (found ${recCards.length})`);
    assert.strictEqual(recCards[0].getAttribute('data-nav'), 'true', 'Recommended card must have data-nav="true"');
  });

  // ===========================================================================
  // SUITE 6: SpatialNav Integration Suite
  // ===========================================================================
  console.log(`\n${C.cyan}▶ SUITE 6: SpatialNav Integration Suite${C.reset}`);

  await check('S6', '1', 'Dynamic Card Navigable Registration (data-nav="true")', async function () {
    var h = createM4Harness();
    h.home.activate();
    await sleep(20);

    var allCards = h.window.document.querySelectorAll('#view-home .card-poster');
    assert.ok(allCards.length >= 10, 'Dynamic cards exist');
    for (var i = 0; i < allCards.length; i++) {
      assert.strictEqual(allCards[i].getAttribute('data-nav'), 'true', `Card ${i} must declare data-nav="true"`);
    }
  });

  await check('S6', '2', 'Horizontal Shelf Scroll Bounds on Dynamic Cards', async function () {
    var h = createM4Harness();
    h.home.activate();
    await sleep(20);

    var cards = h.window.document.querySelectorAll('#shelf-trending-movies .card-poster');
    assert.ok(cards.length >= 10, 'Cards exist on shelf');

    h.nav.setFocus(cards[0]);
    for (var i = 0; i < 8; i++) {
      stepKey(h.window, 'ArrowRight', 39);
    }

    var focused = h.nav.getCurrentFocus();
    assert.ok(focused, 'Element must remain focused after ArrowRight steps');
    var rect = focused.getBoundingClientRect();
    assert.ok(rect.right <= 1824, 'Focused element right edge must not exceed TV safe boundary (1824px)');
  });

  await check('S6', '3', '6-Column Grid 2D Spatial Traversal', async function () {
    var h = createM4Harness();
    h.app.switchView('movies');
    await sleep(20);

    var cards = h.window.document.querySelectorAll('#view-movies .content-grid-6col .card-poster');
    assert.ok(cards.length >= 12, 'Cards exist in grid');

    h.nav.setFocus(cards[3]);
    stepKey(h.window, 'ArrowDown', 40);

    var focused = h.nav.getCurrentFocus();
    assert.strictEqual(focused, cards[9], 'ArrowDown from Card 3 in 6-col grid must advance to Card 9 (col 3, row 1)');
  });

  await check('S6', '4', 'Focus Memory Restoration After Catalog Drilldown', async function () {
    var h = createM4Harness();
    h.app.switchView('movies');
    await sleep(20);

    var cards = h.window.document.querySelectorAll('#view-movies .content-grid-6col .card-poster');
    assert.ok(cards.length >= 8, 'Cards exist');

    h.nav.setFocus(cards[7]);
    // Press Enter to drilldown
    stepKey(h.window, 'Enter', 13);
    await sleep(20);

    assert.strictEqual(h.app.state.currentView, 'details', 'Must enter details view');

    // Press webOS Back Key (461)
    stepKey(h.window, 'Back', 461);
    await sleep(60);

    assert.strictEqual(h.app.state.currentView, 'movies', 'Must return to movies view');
    var restored = h.nav.getCurrentFocus();
    assert.strictEqual(restored, cards[7], 'Focus must restore exactly to previously focused card 7');
  });

  await check('S6', '5', 'Virtual Keyboard to Results Grid Navigation', async function () {
    var h = createM4Harness();
    h.app.switchView('search');
    await sleep(20);

    h.search.query = 'Dune';
    await h.search.executeSearch();

    var spaceKey = h.window.document.querySelector('.key-btn[data-key="SPACE"]');
    assert.ok(spaceKey, 'SPACE key exists');
    h.nav.setFocus(spaceKey);

    // ArrowDown from bottom row escapes trap and lands on first search result
    h.search.jumpToResults();

    var firstResult = h.window.document.querySelector('#search-results-grid .card-poster');
    assert.strictEqual(h.nav.getCurrentFocus(), firstResult, 'Focus must land on first result card');
    assert.strictEqual(h.nav.isTrapped(), false, 'SpatialNav must be untrapped when entering results');
  });

  await check('S6', '6', 'Focus Self-Healing on Dynamic Re-rendering', async function () {
    var h = createM4Harness();
    h.home.activate();
    await sleep(20);

    var cards = h.window.document.querySelectorAll('#shelf-trending-movies .card-poster');
    h.nav.setFocus(cards[3]);

    // Refresh shelf content with new DOM elements
    h.home.renderShelf('shelf-trending-movies', generateMockCards(15, 'movie', 'Refreshed Movie'), 'movie');

    // SpatialNav self-healing handles detached focused elements without throwing
    var currentFocus = h.nav.getCurrentFocus();
    assert.doesNotThrow(function () {
      h.nav.move('ArrowRight');
    }, 'Moving focus after shelf DOM refresh must not throw');
  });

  // ---------------------------------------------------------------------------
  // 7. Results & Summary
  // ---------------------------------------------------------------------------
  console.log(`\n${C.bold}========================================================================${C.reset}`);
  console.log(`${C.bold}Test Execution Summary:${C.reset}`);
  console.log(`  Total Checks:   ${totalChecks}`);
  console.log(`  Passed Checks:  ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red + failedChecks + C.reset : '0'}`);
  console.log(`${C.bold}========================================================================${C.reset}\n`);

  if (failedChecks === 0) {
    console.log(`${C.green}${C.bold}✅ ALL ${totalChecks} AUTOMATED VERIFICATION CHECKS PASSED (100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  } else {
    console.error(`${C.red}${C.bold}❌ ${failedChecks} CHECKS FAILED${C.reset}\n`);
    failureList.forEach(function (f) {
      console.error(`- ${f.label}: ${f.error}`);
    });
    process.exit(1);
  }
}

runMilestone4Tests().catch(function (err) {
  console.error('Fatal unhandled error during test execution:', err);
  process.exit(1);
});

