function getCardFactory() {
  return global.CardFactory || {};
}

var DetailsViewController = {
  initialized: false,
  item: null,
  detailsData: null,
  activeSeason: 1,
  container: null,

  init: function () {
    if (this.initialized) return;
    this.initialized = true;

    this.container = document.getElementById('view-details');
    this.bindActions();
  },

  bindActions: function () {
    var self = this;
    var playBtn = document.getElementById('details-play-btn');
    if (playBtn && !playBtn._hasBoundDetailsPlay) {
      playBtn._hasBoundDetailsPlay = true;
      playBtn.addEventListener('click', function () {
        if (!self.item || !global.CinejoyApp) return;
        var mediaType = self.item.media_type || self.item.type || 'movie';
        var payload = {
          tmdbId: self.item.id || self.item.tmdbId,
          type: mediaType,
          title: self.item.title || self.item.name
        };

        if (mediaType === 'tv') {
          payload.season = self.activeSeason;
          payload.episode = 1;
        }

        global.CinejoyApp.switchView('player', payload);
      });
    }

    // Delegate Episode Card Clicks
    if (this.container && !this.container._hasBoundDetailsClicks) {
      this.container._hasBoundDetailsClicks = true;
      this.container.addEventListener('click', function (e) {
        var epCard = e.target.closest('.card-episode');
        if (!epCard || !global.CinejoyApp) return;

        var season = parseInt(epCard.getAttribute('data-season') || String(self.activeSeason || 1), 10);
        var episode = parseInt(epCard.getAttribute('data-episode') || '1', 10);
        var epTitle = epCard.getAttribute('data-title') || '';
        var item = self.item || self.detailsData || {};

        global.CinejoyApp.switchView('player', {
          tmdbId: item.id || item.tmdbId,
          type: 'tv',
          season: season,
          episode: episode,
          title: item.title || item.name || '',
          episodeTitle: epTitle
        });
      });
    }
  },

  activate: function (item) {
    this.init();
    if (item) {
      this.item = item;
      var mediaType = item.media_type || item.type || (item.first_air_date ? 'tv' : 'movie');
      var id = item.id || item.tmdbId;
      if (id) {
        this.loadDetails(id, mediaType);
      } else {
        this.bindHero(item, mediaType);
      }
    }
  },

  loadDetails: function (id, mediaType) {
    var self = this;
    var mType = mediaType || 'movie';
    if (!this.initialized) this.init();
    if (!this.item) {
      this.item = { id: id, tmdbId: id, type: mType, media_type: mType };
    }
    if (!global.TmdbClient) return;

    return global.TmdbClient.getDetails(mType, id).then(function (data) {
      if (!data || data.error) return;
      self.detailsData = data;
      if (!self.item || !self.item.title) {
        self.item = Object.assign({ id: id, tmdbId: id, type: mType, media_type: mType }, data);
      }
      self.bindHero(data, mType);

      var castList = data.cast || (data.credits && data.credits.cast) || [];
      self.renderCast(castList);

      if (mType === 'tv') {
        var numSeasons = data.numberOfSeasons || data.number_of_seasons || (data.seasons ? data.seasons.length : 1);
        self.renderSeasonSelector(numSeasons);
        self.loadSeason(id, self.activeSeason || 1);
        self.hideRecommendations();
      } else {
        self.hideSeasonSelector();
        var recs = data.recommendations || (data.recommendations && data.recommendations.results) || [];
        if (!recs.length && data.similar) {
          recs = data.similar;
        }
        self.renderRecommendations(recs);
      }
    }).catch(function (err) {
      console.error('[DetailsViewController] Failed to load details:', err);
    });

